function GaugeDescription({ gauge, userDeposit }) {
  const media = useMedia();
  const currencies = useMemo(() => {
    if (!gauge.token0 || !gauge.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        gauge.token0.id,
        parseInt(gauge.token0.decimals),
        gauge.token0.symbol,
        gauge.token0.name
      );
      const token1 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        gauge.token1.id,
        parseInt(gauge.token1.decimals),
        gauge.token1.symbol,
        gauge.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for gauge logos:", error);
      return [void 0, void 0];
    }
  }, [gauge.token0, gauge.token1]);
  const poolDisplayName = gauge.token0?.symbol && gauge.token1?.symbol ? `${gauge.token0.symbol}/${gauge.token1.symbol}` : `${gauge.pool.slice(0, 6)}...${gauge.pool.slice(-4)}`;
  const poolTypeLabel = gauge.poolType === "V2" ? "Volatile" : "Concentrated";
  return <Flex>
      <Flex gap={"$gap8"}>
        <Flex row gap="$gap8" alignItems="center" justifyContent="flex-start">
          <DoubleCurrencyLogo currencies={currencies} size={media.md ? 24 : 40} />
          <Flex flexDirection="column">
            <Flex row gap="$gap6">
              <EllipsisText data-testid="gauge-names" variant={media.md ? "body3" : "body2"}>
                {poolDisplayName}
              </EllipsisText>
              <MouseoverTooltip text="Pool Trading Fee" size={TooltipSize.Max} placement="top">
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body4"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {calculateGaugeFeePercentage(gauge)}%
                </Text>
              </MouseoverTooltip>
            </Flex>
            <Text fontSize={"$mdall"} color={"$greenVibrant"} $platform-web={{ display: media.md ? "none" : "inline" }}>
              {poolTypeLabel}
            </Text>
          </Flex>
        </Flex>

        <Text variant="body4" color={"$greenVibrant"} $platform-web={{ display: media.md ? "inline" : "none" }}>
          {poolTypeLabel}
        </Text>
      </Flex>

      <Separator my={"$spacing12"} />
      <EllipsisText color={"$neutral3"} variant={media.md ? "body4" : "body2"}>
        Total Weight: {Number(gauge.totalWeight) > 0 ? formatVotingPower(gauge.totalWeight) : "0"} veABX
      </EllipsisText>
      
      {
    /* User Deposit Info - Compact Display */
  }
      {userDeposit && (parseFloat(userDeposit.stakedAmount) > 0 || parseFloat(userDeposit.unstakedAmount) > 0) && <>
          <Separator my={"$spacing8"} />
          <Flex row gap={"$gap12"} alignItems="center" flexWrap="wrap">
            {parseFloat(userDeposit.stakedAmount) > 0 && <Flex row alignItems="center" gap={"$gap4"}>
                <TrendingUp size={12} color="#10B981" />
                <EllipsisText color={"$accent1"} variant="body4" fontSize={12}>
                  {parseFloat(userDeposit.stakedAmount).toFixed(2)} Staked
                </EllipsisText>
              </Flex>}
            {parseFloat(userDeposit.unstakedAmount) > 0 && <Flex row alignItems="center" gap={"$gap4"}>
                <DollarSign size={12} color="#6B7280" />
                <EllipsisText color={"$neutral2"} variant="body4" fontSize={12}>
                  {parseFloat(userDeposit.unstakedAmount).toFixed(2)} Available
                </EllipsisText>
              </Flex>}
            {parseFloat(userDeposit.pendingRewards) > 0 && <Flex row alignItems="center" gap={"$gap4"}>
                <Award size={12} color="#F59E0B" />
                <EllipsisText color={"$accent2"} variant="body4" fontSize={12}>
                  +{parseFloat(userDeposit.pendingRewards).toFixed(3)} ABX
                </EllipsisText>
              </Flex>}
          </Flex>
        </>}
    </Flex>;
}
function formatVotingPower(weight) {
  const weightNum = Number(weight) / 1e18;
  if (weightNum < 1e3) return weightNum.toFixed(2);
  if (weightNum < 1e6) return (weightNum / 1e3).toFixed(2) + "K";
  return (weightNum / 1e6).toFixed(2) + "M";
}
export const VotePoolsTable = memo(function VotePoolsTable2({
  userDeposits = []
}) {
  const { data: gauges, isLoading, error } = useAvailableGauges();
  const account = useAccount();
  const { data: userLocks } = useVeABXUserLocks(account.address);
  const selectedLock = useAppSelector(selectSelectedLock);
  return <TableWrapper data-testid="vote-gauges-table">
      <GaugeTable
    gauges={gauges || []}
    loading={isLoading}
    error={error}
    hasLocks={!!userLocks && userLocks.length > 0}
    selectedLock={selectedLock}
    userDeposits={userDeposits}
  />
    </TableWrapper>;
});
const HEADER_TEXT = {
  [VoteTokenSortMethod.POOLS]: "Pools",
  [VoteTokenSortMethod.FEES]: "Fees",
  [VoteTokenSortMethod.TOTAL_REWARDS]: "Total Rewards",
  [VoteTokenSortMethod.INCENTIVES]: "Incentives",
  [VoteTokenSortMethod.V_APR]: "vAPR"
};
