"use strict";
import { formatUnits, parseUnits } from "viem";
export const MAX_LOCK_DURATION_SECONDS = 4 * 365 * 24 * 60 * 60;
export const MIN_LOCK_DURATION_SECONDS = 7 * 24 * 60 * 60;
export const SECONDS_PER_DAY = 24 * 60 * 60;
export const SECONDS_PER_YEAR = 365 * 24 * 60 * 60;
export function calculateVotingPower(lockAmountInTokens, lockDurationInSeconds, tokenDecimals = 18) {
  if (!lockAmountInTokens || lockDurationInSeconds <= 0) {
    return "0";
  }
  try {
    const amount = parseUnits(lockAmountInTokens, tokenDecimals);
    const maxDuration = BigInt(MAX_LOCK_DURATION_SECONDS);
    const duration = BigInt(Math.min(lockDurationInSeconds, MAX_LOCK_DURATION_SECONDS));
    const votingPower = amount * duration / maxDuration;
    return formatUnits(votingPower, tokenDecimals);
  } catch (error) {
    console.error("Error calculating voting power:", error);
    return "0";
  }
}
export function calculateVotingPowerFromDays(lockAmountInTokens, lockDurationInDays, tokenDecimals = 18) {
  const durationInSeconds = lockDurationInDays * SECONDS_PER_DAY;
  return calculateVotingPower(lockAmountInTokens, durationInSeconds, tokenDecimals);
}
export function calculateMaxVotingPower(lockAmountInTokens, tokenDecimals = 18) {
  return calculateVotingPower(lockAmountInTokens, MAX_LOCK_DURATION_SECONDS, tokenDecimals);
}
export function secondsToDays(seconds) {
  return Math.floor(seconds / SECONDS_PER_DAY);
}
export function daysToSeconds(days) {
  return days * SECONDS_PER_DAY;
}
export function isValidLockDuration(durationInDays) {
  const durationInSeconds = durationInDays * SECONDS_PER_DAY;
  return durationInSeconds >= MIN_LOCK_DURATION_SECONDS && durationInSeconds <= MAX_LOCK_DURATION_SECONDS;
}
export function getLockDurationConstraints() {
  return {
    minDays: secondsToDays(MIN_LOCK_DURATION_SECONDS),
    maxDays: secondsToDays(MAX_LOCK_DURATION_SECONDS)
  };
}
export function calculateTimeUntilUnlock(unlockTimestamp) {
  const now = Math.floor(Date.now() / 1e3);
  const unlockTime = parseInt(unlockTimestamp);
  const secondsRemaining = unlockTime - now;
  if (secondsRemaining <= 0) {
    return {
      days: 0,
      hours: 0,
      minutes: 0,
      expired: true
    };
  }
  const days = Math.floor(secondsRemaining / SECONDS_PER_DAY);
  const hours = Math.floor(secondsRemaining % SECONDS_PER_DAY / 3600);
  const minutes = Math.floor(secondsRemaining % 3600 / 60);
  return {
    days,
    hours,
    minutes,
    expired: false
  };
}
export function formatTimeUntilUnlock(unlockTimestamp) {
  const time = calculateTimeUntilUnlock(unlockTimestamp);
  if (time.expired) {
    return "Unlocked";
  }
  if (time.days > 365) {
    const years = Math.floor(time.days / 365);
    const remainingDays = time.days % 365;
    if (remainingDays > 0) {
      return `${years}y ${remainingDays}d remaining`;
    }
    return `${years}y remaining`;
  }
  if (time.days > 0) {
    return `${time.days}d ${time.hours}h remaining`;
  }
  if (time.hours > 0) {
    return `${time.hours}h ${time.minutes}m remaining`;
  }
  return `${time.minutes}m remaining`;
}
export function calculateLockDurationPercentage(durationInDays) {
  const maxDays = secondsToDays(MAX_LOCK_DURATION_SECONDS);
  return Math.min(100, durationInDays / maxDays * 100);
}
export function calculateVotingPowerPercentage(lockAmountInTokens, lockDurationInDays) {
  const maxVotingPower = calculateMaxVotingPower(lockAmountInTokens);
  const currentVotingPower = calculateVotingPowerFromDays(lockAmountInTokens, lockDurationInDays);
  if (parseFloat(maxVotingPower) === 0) return 0;
  return parseFloat(currentVotingPower) / parseFloat(maxVotingPower) * 100;
}
export function parseLockAmount(amount) {
  if (!amount || amount.trim() === "") {
    return { isValid: false, error: "Amount required" };
  }
  const numAmount = parseFloat(amount);
  if (isNaN(numAmount) || numAmount <= 0) {
    return { isValid: false, error: "Amount must be a positive number" };
  }
  if (numAmount < 1e-6) {
    return { isValid: false, error: "Amount too small" };
  }
  return { isValid: true, parsedAmount: numAmount.toString() };
}
export function formatABXAmount(amount, decimals = 18, displayDecimals = 4) {
  try {
    let formattedAmount;
    if (typeof amount === "bigint") {
      formattedAmount = formatUnits(amount, decimals);
    } else if (typeof amount === "string") {
      if (/^\d+$/.test(amount) && amount.length > 15 && !amount.includes(".")) {
        const bigIntAmount = BigInt(amount);
        formattedAmount = formatUnits(bigIntAmount, decimals);
      } else {
        formattedAmount = amount;
      }
    } else {
      formattedAmount = String(amount);
    }
    const num = parseFloat(formattedAmount);
    if (num === 0) return "0";
    if (num < 1e-4) return "< 0.0001";
    if (num >= 1e3) {
      return new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: displayDecimals
      }).format(num);
    }
    return num.toFixed(displayDecimals).replace(/\.?0+$/, "");
  } catch (error) {
    return "0";
  }
}
export function formatVotingPower(amount, decimals = 18, displayDecimals = 2) {
  return formatABXAmount(amount, decimals, displayDecimals);
}
