"use strict";
import { Flex, Text } from "ui/src";
import { useAppSelector, useAppDispatch } from "state/hooks";
import { selectPendingVotes, selectSelectedLock, updatePendingVoteWeight, clearPendingVotes } from "state/voting/slice";
import { useVoterContract } from "hooks/useVoterContract";
import { useModalState } from "hooks/useModalState";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import VoteAllocationRow from "./VoteAllocationRow";
import { useState } from "react";
import { useLockVotingStatus } from "hooks/useVotingStatus";
export default function VotingDetails({ isVoteAble }) {
  const dispatch = useAppDispatch();
  const pendingVotes = useAppSelector(selectPendingVotes);
  const selectedLock = useAppSelector(selectSelectedLock);
  const { vote, resetVotes, transactionState } = useVoterContract();
  const { toggleModal } = useModalState(ModalName.Voting);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const lockVotingStatus = useLockVotingStatus(selectedLock?.id);
  const totalAllocation = pendingVotes.reduce((sum, vote2) => sum + (vote2.weight || 0), 0);
  const hasValidAllocation = totalAllocation > 0 && totalAllocation <= 100;
  const handleAllocate100Percent = () => {
    if (pendingVotes.length === 0) return;
    const evenPercentage = 100 / pendingVotes.length;
    pendingVotes.forEach((vote2) => {
      dispatch(updatePendingVoteWeight({
        poolAddress: vote2.poolAddress,
        weight: evenPercentage
      }));
    });
  };
  const handleSubmitVote = async () => {
    if (!selectedLock || !hasValidAllocation || isSubmitting) return;
    try {
      setIsSubmitting(true);
      const voteAllocations = pendingVotes.filter((vote2) => vote2.weight > 0).map((vote2) => ({
        poolAddress: vote2.poolAddress,
        weight: Math.floor(vote2.weight)
        // Convert to integer weight
      }));
      if (voteAllocations.length === 0) {
        alert("Please allocate voting power to at least one pool");
        return;
      }
      await vote(selectedLock.id, voteAllocations);
      dispatch(clearPendingVotes());
      toggleModal();
    } catch (error) {
      console.error("Vote failed:", error);
      if (error?.message?.includes("AlreadyVotedOrDeposited")) {
        alert('This lock has already voted this epoch. Use "Reset Votes" to clear current votes first.');
      } else {
        alert("Vote transaction failed. Please try again.");
      }
    } finally {
      setIsSubmitting(false);
    }
  };
  const handleResetVotes = async () => {
    if (!selectedLock || isResetting) return;
    try {
      setIsResetting(true);
      await resetVotes(selectedLock.id);
      dispatch(clearPendingVotes());
    } catch (error) {
      console.error("Reset votes failed:", error);
      alert("Reset votes transaction failed. Please try again.");
    } finally {
      setIsResetting(false);
    }
  };
  return <Flex my={"$spacing24"}>
      {!isVoteAble && <Text variant="body3" color={"$neutral3"} textAlign="center">
          You haven't selected any pools for this lock yet.
        </Text>}

      {isVoteAble && <Flex flexDirection="column" gap="$spacing24">
          {
    /* Total Allocation Display */
  }
          <Flex justifyContent="space-between" alignItems="center">
            <Text variant="body2" fontWeight="$medium">Total Allocation:</Text>
            <Text variant="body2" color={totalAllocation > 100 ? "$statusCritical" : "$accent1"}>
              {totalAllocation.toFixed(1)}%
            </Text>
          </Flex>

          {
    /* Allocate 100% Button */
  }
          <Flex
    onPress={handleAllocate100Percent}
    cursor="pointer"
    backgroundColor="$surface3"
    color="$neutral1"
    padding="$spacing12"
    borderRadius="$rounded8"
    justifyContent="center"
    alignItems="center"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
    opacity={pendingVotes.length > 0 ? 1 : 0.5}
    pointerEvents={pendingVotes.length > 0 ? "auto" : "none"}
  >
            <Text variant="buttonLabel2" color="inherit">
              Allocate 100% to Vote
            </Text>
          </Flex>

          {
    /* Vote Allocation Rows */
  }
          <Flex flexDirection="column" gap="$spacing16">
            {pendingVotes.map((vote2) => <VoteAllocationRow
    key={vote2.poolAddress}
    vote={vote2}
  />)}
          </Flex>

          
          {
    /* Show warning for already voted locks */
  }
          {lockVotingStatus.hasVoted && <Flex
    backgroundColor="$surface3"
    padding="$spacing12"
    borderRadius="$rounded8"
    justifyContent="center"
    alignItems="center"
    mt="$spacing16"
  >
              <Text variant="body4" color="$neutral2" textAlign="center">
                ⚠️ This lock has already voted this epoch. Reset will be available next epoch.
              </Text>
            </Flex>}


          {
    /* Validation Messages */
  }
          {totalAllocation > 100 && <Text variant="body4" color="$statusCritical" textAlign="center">
              Total allocation cannot exceed 100%
            </Text>}
          
          {totalAllocation === 0 && <Text variant="body4" color="$neutral3" textAlign="center">
              Please allocate voting power to submit your vote
            </Text>}

          {
    /* Contract Behavior Info */
  }
          <Text variant="body4" color="$neutral2" textAlign="center" mt="$spacing8">
            {lockVotingStatus.hasVoted ? "\u26A0\uFE0F This lock has voted this epoch. Voting decisions are final until next epoch." : "\u2139\uFE0F Each lock can only vote once per epoch. Choose your allocation carefully."}
          </Text>
        </Flex>}
    </Flex>;
}
